const lower=original.toLocaleLowerCase('vi');
const explicitEnglish=/(?:reply|respond|answer|speak|write)\s+(?:to me\s+)?(?:in\s+)?english|(?:in|bằng)\s+english|tiếng anh/i.test(original);
const explicitVietnamese=/(?:reply|respond|answer|speak|write)\s+(?:to me\s+)?(?:in\s+)?vietnamese|(?:in|bằng)\s+vietnamese|tiếng việt/i.test(original);
const viDiacritics=/[ăâđêôơưáàảãạấầẩẫậắằẳẵặéèẻẽẹếềểễệíìỉĩịóòỏõọốồổỗộớờởỡợúùủũụứừửữựýỳỷỹỵ]/i.test(original);
const viMarkers=(lower.match(/\b(?:không|ko|kg|hok|được|dc|mình|mik|bao nhiêu|bn|phần mềm|pm|sản phẩm|sp|anh|chị|em|tôi|bên|giá|dùng|thử|hỗ trợ|cài|bản quyền|với|vs|đâu|nhé|ạ)\b/g)||[]).length;
const technical=new Set(['robot','bot','laser','lidar','bim','iot','agv','kw','ah','kg','mm','m2','m²','zp420b','mg210b','jpd433d','tz432b','clm32150a','fangshi','demo']);
const words=lower.replace(/https?:\/\/\S+/g,' ').match(/[a-z]+/g)||[];
const englishMarkers=words.filter(word=>!technical.has(word)&&['i','me','my','you','your','we','our','a','an','the','to','in','for','and','what','which','where','when','why','how','can','could','would','does','do','is','are','please','need','want','open','save','file','files','support','install','price','cost','latest','download','work','with','speak','say','tell','buy','purchase','english'].includes(word)).length;
let responseLanguage='vi',languageReason='default_vietnamese';
if(explicitEnglish){responseLanguage='en';languageReason='explicit_english_request';}
else if(explicitVietnamese){responseLanguage='vi';languageReason='explicit_vietnamese_request';}
