const englishToVietnamese=new Map([['support','hỗ trợ'],['update','cập nhật'],['version','phiên bản'],['license','bản quyền'],['trial','dùng thử'],['demo','dùng thử'],['install','cài đặt'],['setup','cài đặt'],['config','cấu hình'],['requirement','yêu cầu'],['system','hệ thống'],['feature','tính năng'],['function','chức năng'],['export','xuất'],['import','nhập'],['convert','chuyển đổi'],['deploy','triển khai'],['upgrade','nâng cấp'],['price','giá'],['cost','chi phí'],['open','mở'],['save','lưu'],['file','tệp'],['files','tệp'],['latest','mới nhất'],['download','tải xuống']]);
const translated=normalized.replace(/\b[a-z]+\b/gi,token=>englishToVietnamese.get(token.toLowerCase())||token);
let searchQuery=translated.replace(/^(dạ|ạ|xin chào|chào anh|chào chị|chào em|hello|hi)[,!.\s]*/i,'').replace(/\s+(ạ|nhé|nha|giúp anh|giúp chị|giúp tôi)[.!?\s]*$/i,'').trim();
if(searchQuery.length<3)searchQuery=normalized;
const ambiguousTokens=[...new Set((lower.match(/\b(?:tk|hd|bg|kt)\b/g)||[]))];
const stopWords=new Set(['dạ','ạ','anh','chị','em','tôi','mình','cho','xin','hỏi','là','và','có','không','được','của','với','về','này','đó','như','thế','nào','giúp','muốn','cần','một','các','những']);
const keywords=[...new Set(searchQuery.toLowerCase().replace(/[^a-z0-9à-ỹ\s_.+-]/gi,' ').split(/\s+/).filter(word=>word.length>1&&!stopWords.has(word)))].slice(0,20);
return {json:{...$json,original_question:original,normalized_question:normalized.slice(0,700),search_query:searchQuery.slice(0,700),keywords,response_language_hint:responseLanguage,language_reason:languageReason,ambiguous_tokens:ambiguousTokens}};

