const body = $json.body ?? {};
const entry = body.entry?.[0] ?? {};
const event = entry.messaging?.[0] ?? {};
const message = event.message ?? {};

const pageId = String(entry.id ?? '');
const senderId = String(event.sender?.id ?? '');
const recipientId = String(event.recipient?.id ?? '');
const text = String(message.text ?? '').trim();
const messageId = String(message.mid ?? $execution.id);
const isEcho = message.is_echo === true;

let event_type = 'OTHER';
let customer_id = '';
let page_id = pageId;

if (text) {
  // Tin do Page/Admin gửi ra.
  // Messenger thường đánh dấu is_echo=true.
  // sender.id === entry.id là lớp kiểm tra bổ sung.
  if (isEcho || (pageId && senderId === pageId)) {
    event_type = 'ADMIN';
    customer_id = recipientId;
  }
  // Tin khách gửi vào Page.
  else if (
    senderId &&
    (
      recipientId === pageId ||
      senderId !== pageId
    )
  ) {
    event_type = 'CUSTOMER';
    customer_id = senderId;
  }
}

return {
  json: {
    ...$json,
    messenger_event_type: event_type,
    messenger_page_id: page_id,
    messenger_customer_id: customer_id,
    messenger_sender_id: senderId,
    messenger_recipient_id: recipientId,
    messenger_message_id: messageId,
    messenger_message_text: text,
    messenger_is_echo: isEcho
  }
};

