const latestPageReply=eligiblePageReplies[0]||null,metaCheckOk=!httpFailed&&Boolean(conversation),metaHumanReplied=eligiblePageReplies.length>0,humanReplyDetected=!staleCustomerEvent&&(dbHuman||metaHumanReplied);
