  const pageId = String($('Chuẩn hóa tin nhắn5').item.json.page_id ?? 'unknown');
  throw new Error('CONVERSATION_UPSERT_FAILED: Không tìm thấy Facebook channel/chatbot KOMPAS-3D hợp lệ cho page_id=' + pageId);
}
return { json: { ...$json, conversation_id: value } };

const j=$json;const semantic=j.semantic||{intent:'GENERAL',fields:{},feedback:{},handoff:{}};
